import{c as t,W as o,j as a,n as i}from"./chunks/framework.BqbdRc8q.js";const p=JSON.parse('{"title":"Guides for Workbench","description":"","frontmatter":{"id":"proposal.0002","title":"Guides for Workbench","authors":["markmals","Claude"],"status":"draft","pull-request":"https://github.com/markmals/workbench/pull/2","issues":[],"supersedes":[]},"headers":[],"relativePath":"proposals/0002-guides-for-workbench.md","filePath":"proposals/0002-guides-for-workbench.md"}'),s={name:"proposals/0002-guides-for-workbench.md"};function d(r,e,n,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="guides-for-workbench" tabindex="-1">Guides for Workbench <a class="header-anchor" href="#guides-for-workbench" aria-label="Permalink to “Guides for Workbench”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Writes Workbench&#39;s own user-facing guides, which it currently ships none of despite treating guides as a load-bearing artifact. Adds a check that every command and internal link a guide shows actually resolves, so the documentation cannot rot silently.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>Workbench&#39;s central claim is that a feature is defined by several independent representations, and that guides are one of them. It ships zero guides. A kit that mandates a discipline it does not practise teaches the discipline is optional.</p><p>The gap is not merely embarrassing. The three documents that exist serve different readers and none of them is a guide:</p><table tabindex="0"><thead><tr><th>Document</th><th>Answers</th><th>Reader</th></tr></thead><tbody><tr><td><code>README.md</code></td><td>Should I use this?</td><td>Someone evaluating the kit</td></tr><tr><td><code>PROCESS.md</code></td><td>What is the process?</td><td>Someone who wants the theory</td></tr><tr><td><code>ADOPTING.md</code></td><td>How do I wire this into my harness?</td><td>Someone who just cloned it</td></tr></tbody></table><p>Nothing answers <em>how do I actually run a feature through this?</em> — which is the only question a user has after the first hour. Today they would read <code>AGENTS.md</code>, a contract written for an agent, and infer their own role from it.</p><p>There is a second reason, named in proposal 0001: this is the first change small enough to run end to end through the process without the bootstrapping excuse. Proposal 0001 could not follow the process it defined. This one can, and whether it is pleasant to do is information worth having.</p><h2 id="proposed-solution" tabindex="-1">Proposed solution <a class="header-anchor" href="#proposed-solution" aria-label="Permalink to “Proposed solution”">​</a></h2><p>Six task-oriented guides under <code>guides/</code>, each answering one question a user actually asks, plus a check that keeps their worked examples honest.</p><p>Guides describe what the human does and what the agent does in response. They are not a second copy of <code>AGENTS.md</code> written in the second person — where the agent&#39;s behavior matters to the human, the guide says what to expect, not how the agent achieves it.</p><p><code>ADOPTING.md</code> becomes <code>guides/adapting-your-harness.md</code>, since it is already a guide wearing a root-level filename.</p><h2 id="detailed-design" tabindex="-1">Detailed design <a class="header-anchor" href="#detailed-design" aria-label="Permalink to “Detailed design”">​</a></h2><p><strong>The six guides.</strong></p><table tabindex="0"><thead><tr><th>Guide</th><th>Answers</th></tr></thead><tbody><tr><td><code>getting-started.md</code></td><td>I just cloned this. What do I do?</td></tr><tr><td><code>running-a-feature.md</code></td><td>What actually happens, from idea to merged, and what is my part?</td></tr><tr><td><code>writing-a-good-proposal.md</code></td><td>The template gives me sections. What makes the content worth the effort?</td></tr><tr><td><code>choosing-a-preview.md</code></td><td>What do I wire up so I can exercise a change?</td></tr><tr><td><code>keeping-the-record.md</code></td><td>When does something become a policy, a decision, or neither?</td></tr><tr><td><code>adapting-your-harness.md</code></td><td>How do I wire this into the agent I actually use?</td></tr></tbody></table><p>Each carries <code>id: guide.&lt;slug&gt;</code>, a <code>title</code>, and <code>describes</code> naming the proposals it explains. Each opens with the question it answers, so a reader scanning the sidebar can route themselves.</p><p><strong><code>running-a-feature.md</code> is the load-bearing one.</strong> It walks a single small feature from request to merge, showing what the human types, what <code>mise run status</code> reports at each step, who moves the proposal&#39;s status and when, and what arrives for review. It is the guide that replaces reading <code>AGENTS.md</code> to work out your own role.</p><p><strong>The guides check.</strong> A new <code>tools/check-guides.mjs</code>, dependency-free Node, run by <code>mise run check</code>:</p><ul><li>Every internal markdown link in a guide resolves to a file that exists, and to an anchor that exists when one is given.</li><li>Every <code>mise run &lt;task&gt;</code> shown in a fenced block names a task that exists in <code>mise.toml</code>.</li><li>Every path referenced in prose using backticks and looking like a repository path (<code>.agents/...</code>, <code>tools/...</code>, <code>guides/...</code>) exists.</li></ul><p>This makes Tier 0 what <code>writing-guides</code> currently only asserts in prose: that every worked example actually runs. The enforcement hierarchy requires exactly this conversion where it is possible.</p><p><strong>Pure logic separated from I/O</strong>, matching <code>tools/validate.mjs</code>, so the rules are testable against in-memory guide content without a filesystem.</p><p><strong><code>README.md</code> keeps its role</strong> as the evaluation document and gains a short link list into the guides. It does not become a table of contents.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to “Compatibility”">​</a></h2><p>No behavior changes. <code>ADOPTING.md</code> moves, so its inbound links must move with it — <code>README.md</code>, <code>AGENTS.md</code>, and <code>.agents/hooks/README.md</code> reference it today. Anyone who bookmarked the old path loses it; the repository is a template consumed by copying, so there is no meaningful installed base to break.</p><h2 id="implications-on-adoption" tabindex="-1">Implications on adoption <a class="header-anchor" href="#implications-on-adoption" aria-label="Permalink to “Implications on adoption”">​</a></h2><p>Adopters gain a worked example of the guides discipline, which is the hardest part of the process to convey. They also inherit six guides describing Workbench rather than their own project, so the adoption step must say to delete them — the same instruction that already covers the record.</p><p>The guides check runs against whatever guides a project writes, and will fail on a broken link or a <code>mise run</code> for a task the project has not defined. That is the intended behavior and it needs saying, because the first failure will look like the kit being broken.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><ul><li>Six guides under <code>guides/</code>, with <code>ADOPTING.md</code> moved and its inbound links updated.</li><li><code>tools/check-guides.mjs</code> and its tests, wired into <code>mise run check</code>.</li><li>A link list in <code>README.md</code>.</li><li>An adoption instruction to delete Workbench&#39;s guides.</li></ul><h3 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h3><ul><li><strong>Rewriting <code>PROCESS.md</code> or <code>README.md</code>.</strong> They serve readers the guides do not. <code>PROCESS.md</code> in particular is the authored source of truth and is not a guide.</li><li><strong>Guides for the record artifacts themselves.</strong> <code>proposals/README.md</code> and its siblings already explain their directories to anyone standing in them.</li><li><strong>A tutorial project.</strong> A worked example on a real second repository would teach more than any guide, and is far larger than this.</li></ul><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to “Preview”">​</a></h2><p>The deployed documentation site, which is already wired: <code>.github/workflows/preview.yml</code> publishes it per pull request and comments the URL.</p><p>This is the right preview and an unusually direct one — the guides <em>are</em> the deployed artifact, so reviewing the preview is reviewing the product rather than a proxy for it. Read them in the sidebar, in the order a new user would meet them.</p><h2 id="policies-and-decisions-checked" tabindex="-1">Policies and decisions checked <a class="header-anchor" href="#policies-and-decisions-checked" aria-label="Permalink to “Policies and decisions checked”">​</a></h2><p><code>policies/</code> and <code>decisions/</code> are both empty; both directories were read. Proposal 0001 declined to promote anything into them, so there is still nothing to check against.</p><p>Two rules in <code>.agents/rules/</code> do constrain this work:</p><ul><li><code>enforcement-hierarchy.md</code> — requires attempting a check before writing a rule as prose. The guides check is that attempt applied to <code>writing-guides</code>&#39;s worked-example rule.</li><li><code>code-quality.md</code> — the check separates pure logic from I/O for the same reason the validator does.</li></ul><p>This proposal may be the one that justifies the first real policy: <em>every worked example in a guide must be executable and checked.</em> Recording it is deferred until the check exists and has survived contact with actual guides.</p><h2 id="future-directions" tabindex="-1">Future directions <a class="header-anchor" href="#future-directions" aria-label="Permalink to “Future directions”">​</a></h2><ul><li>Extending the guides check to execute fenced commands in a sandbox rather than merely resolving their task names, which would close the gap between &quot;the command exists&quot; and &quot;the command works&quot;.</li><li>A guide covering the dependent-project workflow, once that workflow exists.</li><li>Screenshots or a recorded session for <code>running-a-feature.md</code>, if prose turns out to be a poor medium for showing an interactive loop.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p><strong>Fold the guides into proposal 0001.</strong> Closes the gap one pull request sooner and avoids a stacked branch. Rejected because 0001 is already a whole-repository rewrite and adding a documentation set makes an over-large pull request harder to review — and because 0001 explicitly predicted this would be its own proposal, so amending it would discard a decision the record already made deliberately.</p><p><strong>Write one long guide instead of six.</strong> Fewer files, and a linear read. Rejected because the questions are asked at genuinely different moments: adapting a harness happens once, choosing a preview happens per project, and running a feature happens constantly. A single document forces every reader through all of it.</p><p><strong>Skip the guides check.</strong> The guides are prose, and a link checker is not free. Rejected because <code>writing-guides</code> already asserts that every worked example must run, and the enforcement hierarchy says a rule that can be a check must be one. A documentation set with no check is the artifact most likely to rot, since nothing else fails when it does.</p><p><strong>Leave <code>ADOPTING.md</code> at the repository root.</strong> It is discoverable there and adopters are told to read it before anything else. Rejected because it is already a guide by the kit&#39;s own definition, and keeping it outside <code>guides/</code> would mean the one document that best demonstrates the form is excluded from the set.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open questions”">​</a></h2><ul><li>[NEEDS CLARIFICATION: Should <code>ADOPTING.md</code> move into <code>guides/</code> as proposed, or stay at the root as the one document a fresh cloner is told to read before the site is even running? Moving it is more consistent; keeping it is more discoverable at the moment of first contact.]</li><li>[NEEDS CLARIFICATION: Six guides is a judgement, not a derivation. Which of them do you actually want — and is <code>writing-a-good-proposal.md</code> redundant now that <code>.agents/templates/PROPOSAL.md</code> carries instructional prose in every section?]</li></ul>',49)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
